"""Representative production-checker controls; fixed actual rows unless mutated explicitly."""
import hashlib,json,os
from pathlib import Path
S=Path(__file__).resolve().parent;R=S.parents[1];O=R/'outputs/mac-poseidon-width3-08';P=S/'project/ShielddSecurity'
module='TransferPoseidonWidth3Absorb08Controls01';ns='ShielddSecurity.'+module
lines=['-- GENERATED by generate_absorption_controls.py; edit generator.','import ShielddSecurity.TransferPoseidonWidth3Absorb08Proof01','set_option maxHeartbeats 900000','set_option maxRecDepth 8192',f'namespace {ns}','open Compiler CompilerIndexed01 Poseidon PoseidonIndexedFolded02 TransferPoseidonWidth3R0008 TransferPoseidonWidth3Absorb08',
'def badInputs (input : Fin 2) : Linear := if input.val=0 then input1 else input0',
'def badCoefficientInputs (input : Fin 2) : Linear := if input.val=0 then input0++[(24286,1)] else input1',
'def badARK : Parameters Int 3 := ⟨(fun index column => if index=0 ∧ column=0 then parameters.ark index column+1 else parameters.ark index column),parameters.mds⟩',
'def badMDS : Parameters Int 3 := ⟨parameters.ark,(fun row column => if row=0 ∧ column=0 then parameters.mds row column+1 else parameters.mds row column)⟩',
'def badFold (column : Fin 3) : FifthHint := if column=0 then .constant 48991097081732275468845314168021420565497297775988823234113406403095118809753 else fifthHints column',
'def badRows : Array Row := originalRows.set! 0 ⟨row0.a++[(24724,1)],row0.b⟩',
'def badMapping : Array Nat := rowMapping.set! 0 1']
def audit(n):lines.extend(['set_option pp.all true in',f'#check @{ns}.{n}',f'#print axioms {ns}.{n}'])
def control(name,rows='originalRows',params='parameters',hints='fifthHints',mapping='rowMapping',domain='24',arity='2',inputs='inputs',component=None):
 call=f'TransferPoseidonWidth3Absorb08.productionCheck {rows} {params} before after {hints} {mapping} {domain} {arity} {inputs}'
 # Computational rejection is isolated to the exact necessary Boolean field;
 # the theorem concludes false for the same complete production checker.
 if component is None:component=f'absorptionCheck {domain} {arity} {inputs} before'
 lines.extend([f'theorem {name} : {call}=false := by',f'  have rejected : {component}=false := by decide +kernel','  simp only [TransferPoseidonWidth3Absorb08.productionCheck,TransferPoseidonWidth3R0008.productionCheck]', '  rw [rejected]', '  simp'])
 audit(name)
control('wrong_domain_rejected',domain='23')
control('wrong_arity_rejected',arity='3')
control('swapped_inputs_rejected',inputs='badInputs')
control('changed_input_coefficient_rejected',inputs='badCoefficientInputs')
control('changed_ark_rejected',params='badARK',component='checkRound p copy originalRows badARK 0 before shifted transformed after fifthHints')
control('changed_mds_rejected',params='badMDS',component='checkRound p copy originalRows badMDS 0 before shifted transformed after fifthHints')
control('changed_native_fold_rejected',hints='badFold',component='checkRound p copy originalRows parameters 0 before shifted transformed after badFold')
control('changed_row_coefficient_rejected',rows='badRows',component='checkRound p copy badRows parameters 0 before shifted transformed after fifthHints')
control('wrong_existing_reverse_index_rejected',mapping='badMapping',component='checkOriginalCoverage p copy originalRows emittedRows badMapping')
lines += [f'end {ns}'];b=('\n'.join(lines)+'\n').encode();p=P/(module+'.lean');tmp=p.with_suffix('.tmp');tmp.write_bytes(b);os.replace(tmp,p)
i=1
while (O/f'absorption-controls-generation{i:02d}.json').exists():i+=1
(O/f'absorption-controls-generation{i:02d}.json').write_text(json.dumps(dict(generator_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),source_sha256=hashlib.sha256(b).hexdigest(),module=module,controls=9,scope='production matcher rejections; reverse index is guard control'),indent=2)+'\n')
